{
  "name": "@genee/opencode-opsx-addon",
  "version": "0.2.2",
  "type": "module",
  "description": "OpenCode addon: OpenSpec workflow tracking + coder/reviewer agents + session title & progress display",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "clean": "rm -rf dist",
    "build": "npm run clean && bun build ./index.ts --outdir=dist --target=node --external=@opencode-ai/plugin && tsc --emitDeclarationOnly",
    "prepublishOnly": "npm run build",
    "typecheck": "tsc --noEmit",
    "test": "bun test"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/iamfat/genee-teams.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "openspec",
    "session-title",
    "opsx"
  ],
  "license": "MIT",
  "peerDependencies": {
    "@opencode-ai/plugin": ">=0.13.7"
  },
  "dependencies": {},
  "devDependencies": {
    "@opencode-ai/plugin": ">=0.13.7",
    "@types/node": "^24.10.1",
    "typescript": "^5.9.3"
  },
  "files": [
    "dist/",
    "README.md"
  ]
}
